-- Editable airport surface geometry (gates/parking positions, ramp/apron areas, taxiways), keyed by
-- airport — the foundation the #164 epic's data-driven departure-timing work keys on. Runways are
-- NOT modeled here; they're already covered by the bundled OurAirports data in feed/runway_db.rs.
-- Geometry is plain jsonb arrays of [lat, lon] pairs, matching this codebase's existing convention
-- (no PostGIS anywhere) — e.g. tmu.tmis.structured.

create table if not exists flow.airport_gate (
    id         text primary key default gen_random_uuid()::text,
    icao       text not null,
    name       text not null,                 -- e.g. "A12", "Cargo Ramp North"
    lat        double precision not null,
    lon        double precision not null,
    source     text not null default 'manual' check (source in ('manual', 'osm', 'crc')),
    updated_by text references identity.users(id) on delete set null,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);
create index if not exists idx_airport_gate_icao on flow.airport_gate(icao);
create trigger trg_airport_gate_updated_at
before update on flow.airport_gate
for each row execute function platform.touch_updated_at();

create table if not exists flow.airport_ramp_area (
    id         text primary key default gen_random_uuid()::text,
    icao       text not null,
    name       text not null,
    kind       text not null default 'ramp' check (kind in ('ramp', 'apron')),
    rings      jsonb not null,                 -- array of rings, each an array of [lat, lon]
    source     text not null default 'manual' check (source in ('manual', 'osm', 'crc')),
    updated_by text references identity.users(id) on delete set null,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);
create index if not exists idx_airport_ramp_area_icao on flow.airport_ramp_area(icao);
create trigger trg_airport_ramp_area_updated_at
before update on flow.airport_ramp_area
for each row execute function platform.touch_updated_at();

create table if not exists flow.airport_taxiway (
    id         text primary key default gen_random_uuid()::text,
    icao       text not null,
    name       text not null default '',
    points     jsonb not null,                 -- array of [lat, lon]
    source     text not null default 'manual' check (source in ('manual', 'osm', 'crc')),
    updated_by text references identity.users(id) on delete set null,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);
create index if not exists idx_airport_taxiway_icao on flow.airport_taxiway(icao);
create trigger trg_airport_taxiway_updated_at
before update on flow.airport_taxiway
for each row execute function platform.touch_updated_at();

-- Proof-of-ingestion-path seed: KDCA's real gates, parking positions, apron areas, and taxiways,
-- fetched live from OpenStreetMap's Overpass API (aeroway=gate|parking_position|apron|taxiway
-- within KDCA's bounding box) — not fabricated data. 57 gates/parking positions, 4 apron polygons,
-- 84 taxiway lines.



